import { NextRequest, NextResponse } from "next/server";
import { getQuarantineConfig, getJsonFile } from "@/lib/githubQuarantine";
import { readLocalScanResults } from "@/lib/localScanResults";
import type { ScanResultListItem, ScanResultsIndex } from "@/lib/av";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GET /api/scan-results?limit=25
 *
 * Reads `scan-results/index.json` — the aggregate data listing generated by
 * the ClamAV GitHub Actions workflow. The listing contains verdicts, filenames,
 * SHA-256 hashes, signatures and timestamps for every published scan.
 *
 * Sources:
 *  - `github`   live from the private quarantine repo (needs GITHUB_PAT)
 *  - `snapshot` local `.cache/scan-results/index.json` written by
 *               `npm run results:pull` (for development without a PAT)
 *
 * Note: this endpoint serves the listing to anyone who can reach the app. Run
 * locally or protect the deployment if filenames/hashes are sensitive.
 */
export async function GET(req: NextRequest) {
  const limitParam = Number(req.nextUrl.searchParams.get("limit") || "25");
  const limit = Number.isFinite(limitParam)
    ? Math.min(Math.max(Math.floor(limitParam), 1), 100)
    : 25;

  const cfg = getQuarantineConfig();

  if (cfg) {
    try {
      const index = await getJsonFile<Partial<ScanResultsIndex>>(
        cfg,
        "scan-results/index.json"
      );
      return respond(index, limit, "github");
    } catch (err) {
      console.error("scan-results error:", err);
      return NextResponse.json(
        { error: "Could not read the ClamAV results listing from GitHub." },
        { status: 500 }
      );
    }
  }

  const snapshot = await readLocalScanResults();
  if (snapshot) return respond(snapshot, limit, "snapshot");

  return NextResponse.json(
    {
      error:
        "ClamAV results are not configured. Add GITHUB_PAT and GITHUB_QUARANTINE_REPOSITORY to .env.local, or run `npm run results:pull` to cache the workflow listing locally.",
    },
    { status: 503 }
  );
}

function respond(
  index: Partial<ScanResultsIndex> | null,
  limit: number,
  source: "github" | "snapshot"
) {
  if (!index) {
    return NextResponse.json({
      status: "empty",
      source,
      generatedAt: null,
      total: 0,
      clean: 0,
      malicious: 0,
      results: [],
      hint:
        "No scan-results/index.json yet. Upload a file from the File tab or `npm run scan:ci` — the GitHub Actions workflow publishes the listing.",
    });
  }

  const all = Array.isArray(index.results)
    ? index.results.filter(isResultListItem)
    : [];
  const results = all.slice(0, limit);
  const clean =
    typeof index.clean === "number"
      ? index.clean
      : all.filter((r) => r.verdict === "clean").length;
  const malicious =
    typeof index.malicious === "number"
      ? index.malicious
      : all.filter((r) => r.verdict === "malicious").length;

  return NextResponse.json({
    status: all.length === 0 ? "empty" : "ok",
    source,
    generatedAt:
      typeof index.generatedAt === "string" ? index.generatedAt : null,
    repository:
      typeof index.repository === "string" ? index.repository : undefined,
    total: typeof index.total === "number" ? index.total : all.length,
    clean,
    malicious,
    results,
    truncated: all.length > results.length,
  });
}

function isResultListItem(value: unknown): value is ScanResultListItem {
  if (typeof value !== "object" || value === null) return false;
  const item = value as Partial<ScanResultListItem>;
  return (
    typeof item.sha256 === "string" &&
    /^[a-f0-9]{64}$/.test(item.sha256) &&
    (item.verdict === "clean" || item.verdict === "malicious")
  );
}
